import Fuse from 'fuse.js';
import { getAllProducts } from '../data/products';

// ============================================
// 1. NLP: СТОП-СЛОВА ТА КЛАВІАТУРНІ РОЗКЛАДКИ
// ============================================

const UKR_STOP_WORDS = new Set([
  'для', 'на', 'в', 'з', 'під', 'по', 'та', 'і', 'або', 'про', 
  'як', 'що', 'при', 'без', 'через', 'від', 'до', 'за', 'над'
]);

// Карта автоматичної зміни розкладки (English -> Ukrainian)
const ENG_TO_UKR = {
  'q':'й','w':'ц','e':'у','r':'к','t':'е','y':'н','u':'г','i':'ш','o':'щ','p':'з','[':'х',']':'ї',
  'a':'ф','s':'і','d':'в','f':'а','g':'п','h':'р','j':'о','k':'л','l':'д',';':'ж','\'':'є',
  'z':'я','x':'ч','c':'с','v':'м','b':'и','n':'т','m':'ь',',':'б','.':'ю'
};

function fixKeyboardLayout(text) {
  // Якщо запит містить суто латиницю, але схожий на укр слова (не схожий на код продукту V1/50)
  if (/^[a-z;\s]+$/i.test(text) && !/\d/.test(text)) {
    return text.toLowerCase().split('').map(char => ENG_TO_UKR[char] || char).join('');
  }
  return text;
}

// ============================================
// 2. NLP: ЛЕГКИЙ УКРАЇНСЬКИЙ СТЕМЕР (STEMMER)
// ============================================
// Алгоритм видалення типових українських закінчень для приведення слів до основи
function stemUkrainianWord(word) {
  if (word.length <= 3) return word;
  
  return word
    .replace(/(іша|іше|іший|іших|ішим|ішими|ішою|іші|іших)$/i, '')
    .replace(/(ому|ого|ому|ими|ими|его|его|ього|ьому)$/i, '')
    .replace(/(ання|ення|іння|яння|ами|ами|ями|ями|ом|ем|єм|ам|ям)$/i, '')
    .replace(/(ий|ій|а|я|е|є|и|і|о|у|ю|ь|ові|еві|ува|юва)$/i, '');
}

// ============================================
// 3. СЛОВНИК СИНОНІМІВ
// ============================================

const SYNONYMS = {
  'розчин': ['суміш', 'заливка', 'бетон', 'mortar', 'grout'],
  'заливання': ['заливка', 'підливка', 'verguss', 'заповнення'],
  'міцний': ['високоміцний', 'потужний', 'сильний', 'посилений'],
  'мороз': ['морозостійкість', 'холод', 'зима', 'антиожеледний'],
  'вода': ['питна', 'водонепроникний', 'двгв', 'dvgw', 'резервуар'],
  'ремонт': ['відновлення', 'реставрація', 'реновація', 'repair'],
  'підлога': ['покриття', 'стяжка', 'floor'],
  'швидкий': ['швидкотвердіючий', 'турбо', 'терміновий', 'аварійний'],
  'анкер': ['анкерування', 'кріплення', 'фіксація', 'anchor'],
  'турбіна': ['генератор', 'двигун', 'компресор', 'енергетика'],
  'міст': ['мостовий', 'опора', 'естакада', 'bridge'],
  'кран': ['підкрановий', 'рейка', 'crane'],
  'корозія': ['іржа', 'захист', 'corrosion'],
  'шов': ['стик', 'зазор', 'зєднання', 'joint'],
  'смола': ['епоксид', 'поліуретан', 'resin'],
  'насос': ['перекачування', 'подача', 'pump']
};

const SYNONYM_GROUPS = Object.entries(SYNONYMS).map(([key, values]) => [key, ...values]);

// ============================================
// 4. ТОКЕНІЗАЦІЯ ТА НОРМАЛІЗАЦІЯ (NLP Pipeline)
// ============================================

function preprocessQuery(query) {
  let text = normalize(query);
  text = fixKeyboardLayout(text);

  // Токенізація на слова
  const rawTokens = text.split(/[^\wа-яєіїґ\d/]+/i).filter(Boolean);

  const cleanTokens = [];
  const stems = [];

  rawTokens.forEach(token => {
    // Якщо токен — стоп-слово, пропускаємо
    if (UKR_STOP_WORDS.has(token)) return;

    cleanTokens.push(token);

    // Додаємо стем-основу слова, якщо це не короткий код/номер
    if (!/\d/.test(token)) {
      const stem = stemUkrainianWord(token);
      if (stem && stem !== token) {
        stems.push(stem);
      }
    }
  });

  return {
    raw: text,
    tokens: cleanTokens,
    stems: stems
  };
}

function normalize(str) {
  return str
    .toLowerCase()
    .trim()
    .replace(/['"«»`’]/g, '')
    .replace(/\s+/g, ' ');
}

// Розширення синонімами на основі токенів та їхніх стемів
function expandQuery({ tokens, stems }) {
  const allTerms = new Set([...tokens, ...stems]);
  const extraTerms = new Set();

  SYNONYM_GROUPS.forEach((group) => {
    const groupStems = group.map(stemUkrainianWord);
    const matched = group.some((term, i) => 
      allTerms.has(term) || allTerms.has(groupStems[i])
    );

    if (matched) {
      group.forEach((term) => extraTerms.add(term));
    }
  });

  return Array.from(new Set([...allTerms, ...extraTerms])).join(' ');
}

// ============================================
// 5. НАЛАШТУВАННЯ FUSE.JS ТА ІНДЕКСУВАННЯ
// ============================================

const fuseOptions = {
  includeScore: true,
  threshold: 0.35,        // Трішки суворіше, ніж 0.4 для зменшення супутнього шуму
  ignoreLocation: true,
  minMatchCharLength: 2,
  useExtendedSearch: true,
  keys: [
    { name: 'title', weight: 0.4 },
    { name: 'subtitle', weight: 0.2 },
    { name: 'searchStems', weight: 0.2 }, // Поле з попередньо згенерованими стемами продуктів
    { name: 'applications', weight: 0.1 },
    { name: 'properties', weight: 0.05 },
    { name: 'features', weight: 0.05 },
  ],
};

let fuseInstance = null;
let indexedAt = 0;

// Підготовка продуктів з NLP-полями перед індексуванням
function prepareProductsForIndex(products) {
  return products.map(p => {
    const fullText = `${p.title} ${p.subtitle || ''} ${p.applications || ''}`;
    const tokens = fullText.toLowerCase().split(/[^\wа-яєіїґ\d/]+/i).filter(Boolean);
    const stems = Array.from(new Set(tokens.map(stemUkrainianWord)));

    return {
      ...p,
      searchStems: stems.join(' ')
    };
  });
}

function getFuse(forceRebuild = false) {
  const products = getAllProducts();
  if (!fuseInstance || forceRebuild || products.length !== indexedAt) {
    const prepared = prepareProductsForIndex(products);
    fuseInstance = new Fuse(prepared, fuseOptions);
    indexedAt = products.length;
  }
  return fuseInstance;
}

// ============================================
// 6. ПУБЛІЧНЕ API
// ============================================

/**
 * Розумний NLP-пошук продуктів.
 */
export function smartSearch(query, limit = 8) {
  if (!query || normalize(query).length < 2) return [];

  const nlpData = preprocessQuery(query);
  const expandedQuery = expandQuery(nlpData);

  const fuse = getFuse();
  const results = fuse.search(expandedQuery, { limit: limit * 2 });

  // 1. Пряма перевірка збігу коду/моделі (наприклад "V1/50", "v1-50", "v150")
  const codeNorm = normalize(query).replace(/[\s/\-_]/g, '');
  const exactCodeMatches = getAllProducts().filter((p) => {
    const idNorm = p.id.toLowerCase().replace(/[\s/\-_]/g, '');
    const titleNorm = p.title.toLowerCase().replace(/[\s/\-_]/g, '');
    return idNorm === codeNorm || idNorm.includes(codeNorm) || titleNorm.includes(codeNorm);
  });

  // 2. Ранжування та об'єднання результатів
  const seen = new Set();
  const combined = [];

  // Точні збіги коду отримують найвищий пріоритет
  exactCodeMatches.forEach((p) => {
    if (!seen.has(p.id)) {
      seen.add(p.id);
      combined.push(p);
    }
  });

  // Результати з Fuse.js
  results.forEach((r) => {
    if (!seen.has(r.item.id)) {
      seen.add(r.item.id);
      combined.push(r.item);
    }
  });

  return combined.slice(0, limit);
}

export function smartSearchAll(query) {
  return smartSearch(query, 100);
}

export function getSuggestions(query, limit = 5) {
  return smartSearch(query, limit).map((p) => p.title);
}

export function rebuildSearchIndex() {
  getFuse(true);
}
